fn concatenate(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    // Pre-allocate enough space for all elements of `a` and `b`.
    let mut result = Vec::with_capacity(a.len() + b.len());
    // Copy all elements from `a` into `result`.
    result.extend_from_slice(&a);
    // Copy all elements from `b` into `result`.
    result.extend_from_slice(&b);
    result
}

